import "server-only";
import type { EntitlementUser } from "@/lib/entitlements";

/** Access resolution never rewrites a provider observation. All deadlines are
 * half-open. An ordinary renewal needs settlement or a signed grace deadline. */
export function resolveSubscriptionLifecycle(
  user: EntitlementUser & { cancelAtPeriodEnd?: boolean },
  now = new Date(Date.now()),
) {
  const start = user.currentPeriodStart,
    end = user.currentPeriodEnd;
  const valid = Boolean(
    user.dodoSubscriptionId && start && end && start < end && start <= now,
  );
  const terminal = ["CANCELLED", "EXPIRED", "FAILED"].includes(
    user.subscriptionStatus,
  );
  const grace =
    valid &&
    user.subscriptionStatus === "PAST_DUE" &&
    user.gracePeriodEnd &&
    user.gracePeriodEnd >= end!
      ? user.gracePeriodEnd
      : null;
  const scheduled = valid && user.cancelAtPeriodEnd;
  const deadline = scheduled ? end : (grace ?? (valid ? end : null));
  const paid =
    user.plan === "PAID" &&
    valid &&
    !(scheduled && now >= end!) &&
    ((user.subscriptionStatus === "ACTIVE" && now < end!) ||
      (grace && now < grace) ||
      (user.subscriptionStatus === "CANCELLED" && scheduled && now < end!));
  const unresolved =
    user.plan === "PAID" &&
    !paid &&
    !terminal &&
    !(scheduled && now >= end!) &&
    !(grace && now >= grace);
  return { paid: Boolean(paid), unresolved: Boolean(unresolved), deadline };
}
